# returns an array of number of bits being zero, then number of bits being one, and so on
# numbers of this array are bytes (uint8)
def compress(image_data):
    compressed = []
    count = 0
    bit_parity = False; # False means bit 0, True bit 1
    # iterate on every byte of image
    for i in range(1, len(image_data)):
        print(f"bit_parity={bit_parity}")
        # iterate on every bit of current byte
        for j in range(8):
            is_bit_set = (image_data[i] & 1 << j) != 0
            print(f"is_bit_set={is_bit_set}")
            if is_bit_set and bit_parity:
            #if is_bit_set and bit_parity and count < 255: #TODO 255 = magic ça continue
                count += 1
                print(f"count={count}")
            else:
                compressed.append(count)
                print(f"append count={count}")
                count = 1
                bit_parity = not bit_parity;
    print(f"append last count={count}")
    compressed.append(count)
    return compressed

